import heapq


def nearest_points(points: list[list[int]], k: int) -> list[list[int]]:
    heap = []                                # max-heap by distance: the key is negated
    for x, y in points:
        heapq.heappush(heap, (-(x * x + y * y), x, y))
        if len(heap) > k:
            heapq.heappop(heap)              # evict the farthest of the k + 1
    return [[x, y] for _, x, y in heap]
